  saveTopicProposalFeedback: defineEndpoint({ id: "topics.proposals.feedback", method: "POST", path: "/topics/proposals/feedback", body: external_exports.object({ taskId: id8, proposalId: id8, reason: topicFeedbackReason, note: external_exports.string().max(1e4).default(""), idempotencyKey: external_exports.string().min(1).max(256) }).strict(), response: external_exports.object({ id: id8, createdAt: iso8601 }).strict(), fr: ["FR-AT-06"] }),
