var jobParams = external_exports.object({ jobId: id8 });
var runParams = external_exports.object({ runId: id8 });
var schedulingOperations = {
  createScheduledJob: defineEndpoint({
    id: "scheduledJobs.create",
    method: "POST",
    path: "/scheduled-jobs",
    body: external_exports.object({
      name: external_exports.string().min(1),
      prompt: external_exports.string().default(""),
      sourceKind: scheduledJobSourceKind,
      target: external_exports.record(external_exports.string(), external_exports.unknown()).default({}),
      schedule: external_exports.string().min(1),
      // cron 表达式
      toolGrants: external_exports.array(external_exports.unknown()).default([])
    }),
    response: scheduledJobResource,
    fr: ["FR-SCHED-JOB-CREATE"]
  }),
  listScheduledJobs: defineEndpoint({
    id: "scheduledJobs.list",
    method: "GET",
    path: "/scheduled-jobs",
    query: paginationQuery.extend({
      sourceKind: scheduledJobSourceKind.optional(),
      enabled: external_exports.coerce.boolean().optional()
    }),
    response: scheduledJobResource,
    isList: true,
    fr: ["FR-SCHED-JOB-LIST"]
  }),
  getScheduledJob: defineEndpoint({
    id: "scheduledJobs.get",
    method: "GET",
    path: "/scheduled-jobs/:jobId",
    params: jobParams,
    response: scheduledJobResource,
    fr: ["FR-SCHED-JOB-GET"]
  }),
  updateScheduledJob: defineEndpoint({
    id: "scheduledJobs.update",
    method: "PATCH",
    path: "/scheduled-jobs/:jobId",
    params: jobParams,
    // 可改 name/prompt/schedule/target/toolGrants/enabled(每个 optional,只改传的字段)。
    body: external_exports.object({
      name: external_exports.string().min(1).optional(),
      prompt: external_exports.string().optional(),
      schedule: external_exports.string().min(1).optional(),
      target: external_exports.record(external_exports.string(), external_exports.unknown()).optional(),
      toolGrants: external_exports.array(external_exports.unknown()).optional(),
      enabled: external_exports.boolean().optional()
    }),
    response: scheduledJobResource,
    fr: ["FR-SCHED-JOB-UPDATE"]
  }),
  setScheduledJobEnabled: defineEndpoint({
    id: "scheduledJobs.setEnabled",
    method: "POST",
    path: "/scheduled-jobs/:jobId/enabled",
    params: jobParams,
    body: external_exports.object({ enabled: external_exports.boolean() }),
    response: scheduledJobResource,
    fr: ["FR-SCHED-JOB-SET-ENABLED"]
  }),
  // 「立即运行」手动触发(data-source-pipeline-design §5/§9 切片 D5)——绕过 cron,即刻产一条
  // ai_task + job_run(fire-and-forget)走同一条确定性采集 runner。走 triggerScheduledJob 的
  // 幂等双闸(同 (job, 自然日) 已有 in-flight run → deduped=true 返回既有,不重复采)。response
  // 是触发结果(非 resource):jobRunId(本次或命中的 run)+ aiTaskId + deduped(是否幂等短路)。
  // 触发编排在 composition 层(persistence-client),不在 module transport —— 后台动作需 dispatch。
  runScheduledJobNow: defineEndpoint({
    id: "scheduledJobs.runNow",
    method: "POST",
    path: "/scheduled-jobs/:jobId/run-now",
    params: jobParams,
    body: external_exports.object({ publicationIds: external_exports.array(id8.max(200)).min(1).max(20).refine((ids) => new Set(ids).size === ids.length, "\u4F5C\u54C1ID\u4E0D\u53EF\u91CD\u590D").optional() }).strict().optional(),
    response: external_exports.object({
      jobRunId: id8,
      aiTaskId: external_exports.string(),
      deduped: external_exports.boolean()
    }),
    fr: ["FR-SCHED-JOB-RUN-NOW"]
  }),
  listJobRunsByJob: defineEndpoint({
    id: "jobRuns.listByJob",
    method: "GET",
    path: "/scheduled-jobs/:jobId/runs",
    params: jobParams,
    query: paginationQuery,
    response: jobRunResource,
    isList: true,
    fr: ["FR-SCHED-RUN-LIST"]
  }),
  getJobRun: defineEndpoint({
    id: "jobRuns.get",
    method: "GET",
    path: "/job-runs/:runId",
    params: runParams,
    response: jobRunResource,
    fr: ["FR-SCHED-RUN-GET"]
  })
};

